record R(string Name, int X) {
 public int Extra = Trace();
 private R(R original) { Print("copy"); Name = original.Name; X = original.X + 1; Extra = 8; }
 static int Trace() { Print("initial"); return 3; }
}
record Required {
 public required string Name;
 public int Number;
 public Required(Required source) { Print("required-copy"); Name = source.Name; Number = source.Number + 1; }
}
int Change() { Print("rhs"); return 10; }
void Main() {
 var r = new R("Ada", 1); var c = r with { Extra = Change() };
 Print(r.X + ":" + r.Extra); Print(c.Name + ":" + c.X + ":" + c.Extra);
 var a = new Required { Name = "Grace", Number = 2 }; var b = a with {};
 Print(b.Name + ":" + b.Number); Print(a.Number);
}
